'''
this is a simple script that was used with-in the blender/bonsaiBIM .ifc
project to remap the viewport color of imported materials into 
the Principled BSDF shader node graph.
this color remap was written to the stucture_mobilehome.usde file
'''
import bpy

# Loop through every single material slot generated by your IFC import
for mat in bpy.data.materials:
    # Verify the material is actively using Blender's node tree network
    if mat.use_nodes and mat.node_tree:
        nodes = mat.node_tree.nodes
        
        # Locate the standard Principled BSDF shader nodes inside the graph
        bsdf = next((node for node in nodes if node.type == 'BSDF_PRINCIPLED'), None)
        
        if bsdf:

            # Extract values from the viewport diffuse_color
            viewport_rgb = mat.diffuse_color # Returns a tuple: (R, G, B, Alpha)
            base_color_vector = (viewport_rgb[0], viewport_rgb[1], viewport_rgb[2], 1.0) #rewrap
            
            # 3. Stamp that exact color vector straight into the Base Color input socket of the node graph!
            bsdf.inputs['Base Color'].default_value = base_color_vector
            
            print(f" -> Successfully synced: '{mat.name}' color parameters to Shader Node.")
